    internal sealed class Skin {
        internal string Name;internal Color Background,Surface,Accent,End,Text,Line;internal bool Legacy;
        static Color C(string value){return ColorTranslator.FromHtml(value);}
        static Skin Make(string name,string background,string surface,string accent,string end){return new Skin{Name=name,Background=C(background),Surface=C(surface),Accent=C(accent),End=C(end),Text=C("#f7f2ec"),Line=C(surface)};}
        internal static readonly Skin[] All={
            Make("Aqua","#131c2b","#293749","#66e2f2","#6676f2"),
            Make("Beige","#211d1a","#39322d","#d8b18c","#e7c9ac"),
            Make("Dark Aero","#1c1c1c","#4f4f4f","#1c1c1c","#4f4f4f"),
            Make("Dorfic","#221c16","#3b3026","#f07902","#fbcc11"),
            Make("Eco","#132019","#293e32","#4ae072","#4ce6a3"),
            new Skin{Name="Legacy",Background=Color.Black,Surface=Color.Black,Accent=Color.White,End=Color.White,Text=Color.White,Line=Color.FromArgb(65,65,65),Legacy=true}
        };
        internal static Skin Find(string name){return All.FirstOrDefault(p=>p.Name==name)??All.First(p=>p.Name=="Dorfic");}
        internal static GraphicsPath Rounded(Rectangle r,int radius){var path=new GraphicsPath();int d=Math.Min(radius*2,Math.Min(r.Width,r.Height));if(d<2){path.AddRectangle(r);return path;}path.AddArc(r.X,r.Y,d,d,180,90);path.AddArc(r.Right-d,r.Y,d,d,270,90);path.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);path.AddArc(r.X,r.Bottom-d,d,d,90,90);path.CloseFigure();return path;}
        internal static Color Mix(Color a,Color b,double amount){return Color.FromArgb((int)(a.R+(b.R-a.R)*amount),(int)(a.G+(b.G-a.G)*amount),(int)(a.B+(b.B-a.B)*amount));}
    }
    internal static class InterfaceFont {
        static PrivateFontCollection collection;static IntPtr memory;static IntPtr gdi;static FontFamily family;
        [DllImport("gdi32.dll")] static extern IntPtr AddFontMemResourceEx(IntPtr data,uint size,IntPtr reserved,out uint count);
        [DllImport("gdi32.dll")] static extern bool RemoveFontMemResourceEx(IntPtr handle);
        internal static Font Create(bool legacy,float size=0){
            if(size<=0)size=legacy?10:7.5f;
            if(legacy)return new Font(SystemFonts.MessageBoxFont.FontFamily,size,FontStyle.Regular);
            if(family==null){using(var stream=typeof(InterfaceFont).Assembly.GetManifestResourceStream("SplatoonAudio.Interface.ttf")){if(stream!=null){byte[] bytes=new byte[stream.Length];stream.Read(bytes,0,bytes.Length);memory=Marshal.AllocCoTaskMem(bytes.Length);Marshal.Copy(bytes,0,memory,bytes.Length);uint count;gdi=AddFontMemResourceEx(memory,(uint)bytes.Length,IntPtr.Zero,out count);collection=new PrivateFontCollection();collection.AddMemoryFont(memory,bytes.Length);family=collection.Families.FirstOrDefault();}}}
            return new Font(family??SystemFonts.MessageBoxFont.FontFamily,size,FontStyle.Regular);
        }
        internal static void Release(){if(collection!=null)collection.Dispose();if(gdi!=IntPtr.Zero)RemoveFontMemResourceEx(gdi);if(memory!=IntPtr.Zero)Marshal.FreeCoTaskMem(memory);collection=null;family=null;memory=gdi=IntPtr.Zero;}
    }
    internal sealed class ActionButton:Button {
        internal Skin Palette;internal bool Primary;
        internal ActionButton(){FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;Height=36;MinimumSize=new Size(60,34);UseVisualStyleBackColor=false;Cursor=Cursors.Hand;SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);}
        protected override void OnPaint(PaintEventArgs e){var p=Palette??Skin.Find("Dorfic");var r=new Rectangle(0,0,Width-1,Height-1);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var shape=Skin.Rounded(r,p.Legacy?0:10)){
                Color color=p.Legacy?Color.FromArgb(22,22,22):Skin.Mix(p.Surface,p.Accent,.12);if(!Enabled)color=Skin.Mix(p.Surface,p.Background,.5);
                using(Brush brush=!p.Legacy&&Primary&&Enabled?(Brush)new LinearGradientBrush(r,p.Accent,p.End,25f):new SolidBrush(color))e.Graphics.FillPath(brush,shape);
                using(var pen=new Pen(Focused?p.Accent:p.Line))e.Graphics.DrawPath(pen,shape);
            }
            Color text=Enabled?p.Text:Color.Gray;if(Primary&&Enabled&&!p.Legacy&&p.Name!="Dark Aero")text=Color.FromArgb(25,25,25);
            TextRenderer.DrawText(e.Graphics,Text,Font,r,text,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);
        }
    }
    internal sealed class Card:Panel {
        internal Skin Palette;
        internal Card(){DoubleBuffered=true;Padding=new Padding(12);Margin=new Padding(0,0,0,10);}
        protected override void OnPaintBackground(PaintEventArgs e){var p=Palette??Skin.Find("Dorfic");e.Graphics.Clear(Parent==null?p.Background:Parent.BackColor);var r=new Rectangle(0,0,Width-1,Height-1);if(r.Width<1||r.Height<1)return;e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var path=Skin.Rounded(r,p.Legacy?0:12)){using(var fill=new SolidBrush(p.Surface))e.Graphics.FillPath(fill,path);using(var pen=new Pen(p.Line))e.Graphics.DrawPath(pen,path);}}
    }
    internal sealed class WaveformView:Control {
        internal Skin Palette;float[] peaks=new float[0];double position;Bitmap cached;internal Action<double> Seek;
        internal WaveformView(){DoubleBuffered=true;SetStyle(ControlStyles.ResizeRedraw,true);Cursor=Cursors.Hand;MinimumSize=new Size(100,90);}
        internal void SetPeaks(float[] value){peaks=value??new float[0];position=0;DropCache();Invalidate();}
        internal void SetPosition(double value){position=Math.Max(0,Math.Min(1,value));Invalidate();}
        internal void DropCache(){if(cached!=null){cached.Dispose();cached=null;}}
        protected override void OnSizeChanged(EventArgs e){DropCache();base.OnSizeChanged(e);}
        protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button==MouseButtons.Left&&peaks.Length>0&&Seek!=null)Seek(Math.Max(0,Math.Min(1,(double)e.X/Math.Max(1,Width-1))));}
        protected override void OnPaint(PaintEventArgs e){var p=Palette??Skin.Find("Dorfic");if(cached==null&&Width>0&&Height>0){cached=new Bitmap(Width,Height);using(var g=Graphics.FromImage(cached)){g.Clear(p.Background);using(var grid=new Pen(p.Line)){g.DrawLine(grid,0,Height/2,Width,Height/2);if(!p.Legacy){for(int i=1;i<4;i++)g.DrawLine(grid,Width*i/4,0,Width*i/4,Height);}}
                    using(var pen=new Pen(p.Name=="Dark Aero"?Color.LightGray:p.Accent)){for(int x=0;x<Width&&peaks.Length>0;x++){int first=(int)((long)x*peaks.Length/Width),last=Math.Min(peaks.Length-1,Math.Max(first,(int)((long)(x+1)*peaks.Length/Width)));float peak=0;for(int i=first;i<=last;i++)peak=Math.Max(peak,peaks[i]);int h=(int)(peak*(Height-10)*.5);g.DrawLine(pen,x,Height/2-h,x,Height/2+h);}}
                }}if(cached!=null)e.Graphics.DrawImageUnscaled(cached,0,0);if(peaks.Length>0)using(var pen=new Pen(Color.White,1))e.Graphics.DrawLine(pen,(int)(position*(Width-1)),0,(int)(position*(Width-1)),Height);
            if(peaks.Length==0)TextRenderer.DrawText(e.Graphics,"Select a track to preview its waveform",Font,ClientRectangle,p.Text,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);
        }
        protected override void Dispose(bool disposing){if(disposing)DropCache();base.Dispose(disposing);}
    }
    internal sealed class ThemeRenderer:ToolStripProfessionalRenderer {
        readonly Skin skin;internal ThemeRenderer(Skin skin){this.skin=skin;RoundedEdges=!skin.Legacy;}
        protected override void OnRenderToolStripBackground(ToolStripRenderEventArgs e){e.Graphics.Clear(skin.Surface);}
        protected override void OnRenderMenuItemBackground(ToolStripItemRenderEventArgs e){if(e.Item.Selected)using(var b=new SolidBrush(skin.Legacy?Color.FromArgb(45,45,45):Skin.Mix(skin.Surface,skin.Accent,.2)))e.Graphics.FillRectangle(b,new Rectangle(2,0,e.Item.Width-4,e.Item.Height));}
        protected override void OnRenderItemText(ToolStripItemTextRenderEventArgs e){e.TextColor=skin.Text;base.OnRenderItemText(e);}
    }

