        Track[] Selected(){return tracks.SelectedItems.Cast<ListViewItem>().Select(i=>(Track)i.Tag).ToArray();}
        void RefreshList(){if(document==null)return;int selected=Current()==null?-1:Current().Index;tracks.BeginUpdate();tracks.Items.Clear();foreach(var t in document.Tracks){if(t.Name.IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)<0)continue;var item=new ListViewItem(new[]{t.Name,Clock(t.Duration),t.Rate/1000.0+" kHz / "+t.Channels+" ch",replacementNames.ContainsKey(t.Index)?replacementNames[t.Index]:"Original"}){Tag=t};tracks.Items.Add(item);if(t.Index==selected)item.Selected=true;}tracks.EndUpdate();if(tracks.SelectedItems.Count==0&&tracks.Items.Count>0)tracks.Items[0].Selected=true;ShowDetails();UpdateButtons();}
        void ShowDetails(){var t=Current();if(t==null){details.Text="Select one track to see its details.";replacementLabel.Text="Keep original audio";}else{details.Text=t.Name+"\n\nDuration    "+Clock(t.Duration)+"\nSample rate    "+t.Rate.ToString("N0")+" Hz\nChannels    "+t.Channels+"\nEncoding    "+(t.Magic=="BWAV"?(t.Codec==0?"PCM16":"DSP-ADPCM"):"Nintendo stream")+"\nPlayback    "+(t.LoopEnd>=0?"Loops":"Plays once")+(t.Channels>2?"\n\nPreview uses the first stereo pair. Extraction keeps all channels.":"");replacementLabel.Text=replacementNames.ContainsKey(t.Index)?replacementNames[t.Index]:"Keep original audio";trackLabel.Text=t.Name;}UpdateButtons();}
        void UpdateButtons(){bool ready=document!=null&&!workBusy;open.Enabled=!workBusy;search.Enabled=ready;tracks.Enabled=ready;extract.Enabled=ready&&tracks.SelectedItems.Count>0;extractAll.Enabled=ready;save.Enabled=ready&&!document.ReadOnly;choose.Enabled=ready&&Current()!=null&&Current().CanReplace;clear.Enabled=ready&&Current()!=null&&document.Replacements.ContainsKey(Current().Index);play.Enabled=restart.Enabled=stop.Enabled=preview!=null&&!workBusy;previewSource.Enabled=ready&&Current()!=null&&document.Replacements.ContainsKey(Current().Index);save.Text="Save as "+(document==null?".bars.zs":document.Extension);}
        static string Clock(double value){long n=(long)Math.Round(Math.Max(0,value)*100);return (n/6000).ToString("D2")+":"+(n/100%60).ToString("D2")+"."+(n%100).ToString("D2");}
        static string Friendly(Exception e){if(e is UnauthorizedAccessException)return "Access denied. Choose a writable folder or close the other application.";if(e is IOException&&!(e is InvalidDataException))return "The file could not be read or written. Check that it exists, is fully downloaded, and is not locked by another application.";return e is InvalidDataException||e is InvalidOperationException||e is ArgumentException?e.Message:"The audio file could not be processed. It may be damaged or use an unsupported format.";}
        void Error(Exception e){status.Text=Friendly(e);if(SnapshotPath!=null){TestFailure=status.Text;return;}MessageBox.Show(this,status.Text,"Audio converter",MessageBoxButtons.OK,MessageBoxIcon.Warning);}
        bool Discard(){return !dirty||MessageBox.Show(this,"Discard unsaved audio replacements?","Unsaved replacements",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes;}
        void SetBusy(bool value,string message){workBusy=value;status.Text=message;progress.Visible=value;progress.Style=ProgressBarStyle.Marquee;UpdateButtons();}
        internal async void OpenPath(string path){if(workBusy||!Discard())return;SetBusy(true,"Opening "+Path.GetFileName(path)+"...");previewToken++;Player.SetSource(null);preview=null;wave.SetPeaks(null);try{var doc=await Task.Run(()=>new AudioDocument(path));if(IsDisposed)return;document=doc;replacementNames.Clear();dirty=false;search.Clear();fileLabel.Text=Path.GetFileName(path)+"\n\n"+doc.Kind+" / "+doc.Tracks.Count+" tracks";SetBusy(false,"Opened "+Path.GetFileName(path)+".");RefreshList();if(Current()!=null)PreparePreview();}catch(Exception e){SetBusy(false,"Could not open audio.");Error(e);}}
        void OpenDialog(){using(var d=new OpenFileDialog{Title="Open audio file",Filter="Game audio|*.bars;*.bars.zs;*.bwav;*.bwav.zs;*.bfstm;*.bfstm.zs|All files|*.*",CheckFileExists=true})if(d.ShowDialog(this)==DialogResult.OK)OpenPath(d.FileName);}
        async void PreparePreview(){
            if(workBusy)return;int token=++previewToken;var doc=document;var t=Current();preview=null;previewTrack=null;Player.SetSource(null);wave.SetPeaks(null);UpdateButtons();if(doc==null||t==null)return;bool replacement=previewSource.SelectedIndex==1&&doc.Replacements.ContainsKey(t.Index);PcmAudio assigned=replacement?doc.Replacements[t.Index]:null;status.Text="Preparing "+t.Name+"...";
            try{var result=await Task.Run(()=>{var audio=assigned??doc.Decode(t);return Tuple.Create(audio,audio.Peaks());});if(IsDisposed||token!=previewToken||document!=doc)return;preview=result.Item1;previewTrack=t;wave.SetPeaks(result.Item2);Player.SetSource(preview);timeLabel.Text="00:00.00 / "+Clock(preview.Duration);status.Text="Ready.";UpdateButtons();if(pendingPlay){pendingPlay=false;Player.Play();}}
            catch(Exception e){if(token==previewToken&&!IsDisposed)Error(e);}
        }
        void TogglePlay(){if(preview==null){pendingPlay=true;return;}if(Player.State==1)Player.Pause();else Player.Play();}
        async void ChooseReplacement(){var t=Current();if(t==null||workBusy)return;using(var d=new OpenFileDialog{Title="Choose replacement WAV",Filter="16-bit PCM WAV|*.wav",CheckFileExists=true})if(d.ShowDialog(this)==DialogResult.OK){string path=d.FileName;SetBusy(true,"Reading replacement WAV...");try{var pcm=await Task.Run(()=>PcmAudio.ReadWave(path));document.SetReplacement(t,pcm);replacementNames[t.Index]=Path.GetFileName(path);dirty=true;SetBusy(false,"Replacement ready.");RefreshList();previewSource.SelectedIndex=1;PreparePreview();}catch(Exception e){SetBusy(false,"Replacement was not added.");Error(e);}}}
        void RemoveReplacement(){var t=Current();if(t==null||workBusy)return;document.Replacements.Remove(t.Index);replacementNames.Remove(t.Index);dirty=true;previewSource.SelectedIndex=0;RefreshList();PreparePreview();}
        async void Extract(bool all){if(document==null||workBusy)return;Track[] chosen=all?document.Tracks.ToArray():Selected();if(chosen.Length==0)return;using(var dialog=new FolderBrowserDialog{Description="Choose a folder for extracted WAVs"})if(dialog.ShowDialog(this)==DialogResult.OK){string folder=dialog.SelectedPath;if(chosen.Any(t=>File.Exists(Path.Combine(folder,t.Index.ToString("D3")+"_"+AudioDocument.SafeName(t.Name)+".wav")))&&MessageBox.Show(this,"Some extracted WAVs already exist. Replace them?","Extract WAVs",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;SetBusy(true,"Extracting WAVs...");try{await Task.Run(()=>document.Extract(chosen,folder));SetBusy(false,"Extracted "+chosen.Length+" WAVs.");}catch(Exception e){SetBusy(false,"Extraction stopped.");Error(e);}}}
        async void SaveDialog(){if(document==null||workBusy)return;using(var d=new SaveFileDialog{Title="Save a new audio file",Filter="Game audio (*"+document.Extension+")|*"+document.Extension,DefaultExt=document.Extension.TrimStart('.'),AddExtension=true,FileName=AudioDocument.BaseName(Path.GetFileName(document.Source))+document.Extension,OverwritePrompt=true})if(d.ShowDialog(this)==DialogResult.OK){string path=document.NormalizeOutput(d.FileName);if(string.Equals(path,document.Source,StringComparison.OrdinalIgnoreCase)){Error(new InvalidOperationException("Choose a different name or folder. Your original file is never overwritten."));return;}if(!string.Equals(path,d.FileName,StringComparison.OrdinalIgnoreCase)&&File.Exists(path)&&MessageBox.Show(this,"The normalized filename already exists. Replace "+Path.GetFileName(path)+"?","Save audio",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;SetBusy(true,"Saving audio...");try{await Task.Run(()=>document.Save(path,message=>{if(IsHandleCreated&&!IsDisposed)BeginInvoke((Action)(()=>status.Text=message));}));dirty=false;SetBusy(false,"Saved "+Path.GetFileName(path)+". Original file unchanged.");}catch(Exception e){SetBusy(false,"Save failed.");Error(e);}}}
        void Tick(object sender,EventArgs e){if(preview!=null){double seconds=(double)Player.PositionFrames/preview.Rate;wave.SetPosition((double)Player.PositionFrames/Math.Max(1,preview.Frames));timeLabel.Text=Clock(seconds)+" / "+Clock(preview.Duration);}play.Text=Player.State==1?"Pause":"Play";if(Player.Error!=null&&Player.Error!=lastError){lastError=Player.Error;status.Text=lastError;if(SnapshotPath!=null)TestFailure=lastError;}
            if(SnapshotPath!=null&&PreviewReady&&!workBusy){if(VerifyPlayback&&!snapshotStarted){Player.Volume=0;Player.Play();snapshotStarted=true;return;}if(VerifyPlayback&&Player.BytesWritten==0)return;Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(SnapshotPath)));using(var bitmap=new Bitmap(Width,Height)){DrawToBitmap(bitmap,new Rectangle(0,0,Width,Height));bitmap.Save(SnapshotPath,System.Drawing.Imaging.ImageFormat.Png);}SnapshotPath=null;timer.Stop();BeginInvoke((Action)(()=>Close()));}
        }
        void KeysPressed(object sender,KeyEventArgs e){if(e.Control&&e.KeyCode==Keys.O){OpenDialog();e.SuppressKeyPress=true;}else if(e.Control&&e.Shift&&e.KeyCode==Keys.S){SaveDialog();e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.R){Player.Restart();e.SuppressKeyPress=true;}else if(e.KeyCode==Keys.Space&&!(ActiveControl is TextBox)){TogglePlay();e.SuppressKeyPress=true;}}
        void ClosingRequest(object sender,FormClosingEventArgs e){if(workBusy){e.Cancel=true;return;}if(SnapshotPath==null&&!Discard()){e.Cancel=true;return;}previewToken++;timer.Stop();Player.Dispose();}
        protected override void Dispose(bool disposing){if(disposing){timer.Dispose();Player.Dispose();foreach(var font in fonts)font.Dispose();}base.Dispose(disposing);}
    }
}
